// Uploads the built artifact to the release bucket.
const fs = require("fs");
const https = require("https");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function putObject(bucket, key, body, contentType) {
  // Minimal S3 PUT Object request. Works against S3-compatible endpoints or
  // with SigV4 signing when credentials are provided via the environment
  // (S3_ACCESS_KEY_ID / S3_SECRET_ACCESS_KEY, S3_ENDPOINT, S3_REGION).
  const endpoint =
    process.env.S3_ENDPOINT ||
    `${bucket}.s3.${process.env.S3_REGION || "eu-central-1"}.amazonaws.com`;
  const host = process.env.S3_ENDPOINT ? process.env.S3_ENDPOINT : endpoint;
  const port = process.env.S3_ENDPOINT_PORT || 443;
  const headers = {
    host,
    "content-length": Buffer.byteLength(body),
  };
  if (contentType) headers["content-type"] = contentType;

  const accessKeyId = process.env.S3_ACCESS_KEY_ID;
  const secretAccessKey = process.env.S3_SECRET_ACCESS_KEY;
  if (accessKeyId && secretAccessKey) {
    const crypto = require("crypto");
    const region = process.env.S3_REGION || "eu-central-1";
    const now = new Date();
    const amzDate = now.toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
    const dateStamp = amzDate.slice(0, 8);

    const signedHeaderNames = Object.keys(headers).sort().join(";");
    const canonicalHeaders =
      Object.keys(headers)
        .sort()
        .map((n) => `${n}:${headers[n]}`)
        .join("\n") + "\n";
    const payloadHash = crypto.createHash("sha256").update(body).digest("hex");
    const canonicalRequest = [
      "PUT",
      `/${key}`,
      "",
      canonicalHeaders,
      signedHeaderNames,
      payloadHash,
    ].join("\n");
    const scope = `${dateStamp}/${region}/s3/aws4_request`;
    const stringToSign = [
      "AWS4-HMAC-SHA256",
      amzDate,
      scope,
      crypto.createHash("sha256").update(canonicalRequest).digest("hex"),
    ].join("\n");
    const hmac = (key, data) =>
      crypto.createHmac("sha256", key).update(data).digest();
    const kDate = hmac(`AWS4${secretAccessKey}`, dateStamp);
    const kRegion = hmac(kDate, region);
    const kService = hmac(kRegion, "s3");
    const kSigning = hmac(kService, "aws4_request");
    const signature = crypto
      .createHmac("sha256", kSigning)
      .update(stringToSign)
      .digest("hex");
    headers.authorization =
      `AWS4-HMAC-SHA256 Credential=${accessKeyId}/${scope}, ` +
      `SignedHeaders=${signedHeaderNames}, Signature=${signature}`;
    headers["x-amz-date"] = amzDate;
  }

  return new Promise((resolve, reject) => {
    const req = https.request(
      { host, port, path: `/${key}`, method: "PUT", headers },
      (res) => {
        res.resume();
        res.on("end", () =>
          res.statusCode >= 200 && res.statusCode < 300
            ? resolve({ statusCode: res.statusCode })
            : reject(new Error(`PUT ${key} failed with HTTP ${res.statusCode}`))
        );
      }
    );
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  const result = await putObject(BUCKET, name, body, "application/javascript");
  console.log(`uploaded ${name} (${body.length} bytes)`);
  console.log(`  -> s3://${BUCKET}/${name} (HTTP ${result.statusCode})`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
